  "Codex 桌面进程身份已变化，请重新初始化连接": "Codex 데스크톱 프로세스 ID가 변경되었습니다. 연결을 다시 초기화하십시오.",
  "Codex 桌面进程已变化，请重新初始化连接": "Codex 데스크톱 프로세스가 변경되었습니다. 연결을 다시 초기화하십시오.",
  "运行中的 Codex 使用其他配置目录，不能初始化此接入": "실행 중인 Codex는 다른 구성 디렉터리를 사용합니다. 이 연결을 초기화할 수 없습니다.",
