  "未能确认 Codex 原生共享连接，请重新初始化连接": "Codex 네이티브 공유 연결을 확인할 수 없습니다. 연결을 다시 초기화하십시오.",
  "此前删除未确认，以上为仍存在的聊天。不会自动重试；请先在原客户端核对，再决定是否重新删除。": "이전 삭제가 확인되지 않았습니다. 이런 채팅은 아직도 존재합니다. 다시 삭제할지 여부를 결정하기 전에 원래 클라이언트를 확인하십시오. 자동 재시도는 없습니다.",
