  "此环境尚无可复用模型目录，可手动填写；不会为读取目录启动 CLI 会话。": "이 환경에서는 재사용 가능한 모델 카탈로그가 없습니다. 모델을 수동으로 입력하세요. 이 목록을 읽어도 CLI 세션이 시작되지 않습니다.",
