  "强制释放此连接…": "이 연결을 강제로 해제합니다...",
  "停止任务并释放所选…": "선택한 작업 중지 후 연결 해제…",
  "历史操作回执": "작업 기록",
  "正在核对释放范围…": "연결 해제 범위 확인 중…",
  "正在提交释放请求…": "연결 해제 요청 중…",
  "CLI 范围尚未核验，请重新检查": "CLI 범위가 확인되지 않았습니다. 다시 확인하세요.",
  "当前无法核验此 CLI 连接及原生进程。": "이 CLI 연결 및 네이티브 프로세스는 현재 확인할 수 없습니다.",
  "返回连接列表": "연결",
  "确认强制释放？": "강제로 연결을 해제할까요?",
  "确认释放 CLI 连接？": "CLI 연결을 해제하시겠습니까?",
  "将中断运行中或状态未知的任务；范围可能包含未列出的会话。聊天历史保留。": "이로 인해 실행 중이거나 확인되지 않은 작업이 중단됩니다. 범위에는 나열되지 않은 세션이 포함될 수 있습니다. 채팅 기록은 보존됩니다.",
  "此操作会退出此配置的整个共享 CLI 服务，包含其它连接。默认等待全部任务安全结束；期间请勿从其它客户端发起新任务。": "그러면 다른 연결을 포함하여 이 구성에 대한 전체 공유 CLI 서비스가 종료됩니다. 모든 작업이 안전하게 완료될 때까지 기다립니다. 그동안 다른 클라이언트에서 새 작업을 시작하지 마십시오.",
  "将停止所选连接的任务并逐条释放，聊天历史保留。": "선택한 연결에서 작업을 중지하고 각 연결을 해제합니다. 채팅 기록은 보존됩니다.",
  "逐条等待所选 CLI 任务安全结束后释放连接，不退出其它配置。": "선택한 CLI 작업이 안전하게 완료될 때까지 기다렸다가 각 연결을 해제합니다. 다른 구성은 종료되지 않습니다.",
  "此操作暂不支持取消等待；关闭面板不会取消已提交的释放。": "현재 대기 취소는 지원되지 않습니다. 패널을 닫아도 제출된 릴리스는 취소되지 않습니다.",
  "确认强制释放": "강제 해제",
  "确认释放": "연결 해제",
  "释放 CLI 连接": "CLI 연결 해제",
  "释放连接": "연결 해제",
