  "释放全部": "모두 해제",
  "选择全部": "모두 선택",
  "停止并释放…": "작업 중지 후 연결 해제…",
  "停止任务并释放连接？": "작업을 중지하고 연결을 해제하시겠습니까?",
  "确认停止并释放": "중지 확인 및 해제",
  "等待任务完成": "작업이 완료되기를 기다리는 중",
  "正在释放": "연결 해제 중",
  "连接已释放": "연결이 해제되었습니다.",
  "网关连接已释放，原生占用待核对": "게이트웨이 연결이 끊어졌습니다. 네이티브 소유권 확인이 필요합니다.",
  "没有由网关持有的 CLI 连接": "이 게이트웨이에 의해 유지되는 CLI 연결이 없습니다.",
  "请选择需要释放的 CLI 连接": "해제할 CLI 연결을 선택하세요.",
  "已提交释放请求": "연결 해제 요청됨",
  "释放当前网关持有的连接，保留聊天历史。运行中的任务默认完成后释放。": "이 게이트웨이가 보유한 연결을 해제하고 채팅 기록을 유지하세요. 실행 중인 작업은 기본적으로 릴리스 전에 완료됩니다.",
  "将停止所选会话正在运行的任务并释放连接，聊天历史会保留。": "선택한 채팅에서 실행 중인 작업을 중지하고 연결을 해제합니다. 채팅 기록이 유지됩니다.",
  "纯文本": "일반 텍스트",
  "管理 ZCode 桌面应用与手机接入。": "ZCode 데스크톱 앱 및 전화 액세스를 관리합니다.",
  "ZCode 已安装，当前没有可用的本机聊天连接。": "ZCode가 설치되었습니다. 실시간 로컬 채팅 연결을 사용할 수 없습니다.",
  "原生会话已接入": "네이티브 세션에 연결됨",
  "请先停用 ZCode 手机接入并退出原 App，再切换已保存账号": "저장된 계정을 전환하기 전에 ZCode 전화 액세스를 비활성화하고 데스크톱 앱을 종료하세요.",
  "按会话接入": "채팅당 연결",
  "此聊天尚无已保存的消息。": "이 채팅에는 아직 저장된 메시지가 없습니다.",
  "可在聊天中继续原生会话。": "네이티브 세션을 계속하려면 채팅을 엽니다.",
  "已接入原窗口，可发送文字消息。": "원래 창에 연결되었습니다. 문자를 보낼 수 있습니다.",
  "可先查看历史；继续会话时会在电脑上打开此原生聊天。": "대화 기록을 확인할 수 있습니다. 계속하면 컴퓨터에서 이 채팅이 열립니다.",
