  "当前安装的 ZCode 不支持此本机实时连接。": "이 ZCode 설치는 이 로컬 라이브 연결을 지원하지 않습니다.",
  "未检测到可接入的 ZCode 本机实时连接。": "호환되는 로컬 ZCode 연결을 찾을 수 없습니다.",
  "正常退出确认": "정상 종료 확인",
  "通过原生方式退出；无法核验任务时需要再次确认。": "앱의 네이티브 작업 사용을 종료합니다. 확인되지 않은 작업에는 확인이 필요합니다.",
  "当前无法核验所有任务。正常退出可能中断正在运行的任务或等待中的审批，是否继续？": "일부 작업을 확인할 수 없습니다. 종료하면 실행 중인 작업이 중단되거나 승인이 보류될 수 있습니다. 계속하다?",
  "Codex 恢复退出确认": "Codex 복구 종료 확인",
  "连接重建失败，可能无法核验全部任务。正常退出仍可能中断无法确认的任务；已知运行任务会阻止退出。请确认接受此风险，退出后再手动开启 Codex。": "연결 재구축에 실패하여 일부 작업을 확인하지 못할 수 있습니다. 정상적인 종료는 해당 작업을 방해할 수 있습니다. 알려진 활성 작업은 여전히 ​​종료를 차단합니다. 이 위험을 확인한 다음 종료된 후 Codex를 수동으로 시작하십시오.",
  "尚未连接原桌面会话。可再次重建连接；若仍失败，可在应用管理中核对任务后重启 Codex。": "데스크톱 연결이 끊어졌습니다. 다시 연결해 보세요. 연결되지 않으면 앱 관리에서 진행 중인 작업을 확인한 뒤 Codex를 다시 시작하세요.",
  "重建连接后仍无法连接原桌面会话。可在应用管理中正常退出并重新启动 Codex；退出前请核对任务。": "재구축 후에도 원래 데스크톱 세션에 계속 연결할 수 없습니다. 앱 관리를 사용하여 Codex를 정상적으로 종료하고 다시 시작하세요. 종료하기 전에 작업을 검토하십시오.",
