  "账号和 API 请在已绑定的第三方客户端中管理": "바인딩된 타사 클라이언트에서 계정 및 API를 관리합니다.",
  "原生分类结果待核对；不会重复提交，请先在原客户端核对": "네이티브 조직 결과를 확인해야 합니다. 원래 클라이언트를 확인하십시오. 이 작업은 다시 제출되지 않습니다.",
  "此前分类操作仍待核对；不会重复提交，请先在原客户端核对": "이전 조직 운영에는 아직 확인이 필요합니다. 원래 클라이언트를 확인하십시오. 다시 제출되지 않습니다.",
