  "将停止此聊天及其子任务，并在确认停止后归档。聊天记录会保留，未完成任务不会自动续跑。": "이 채팅과 하위 작업을 중지한 다음 중지되었는지 확인한 후 보관하세요. 채팅 기록은 유지됩니다. 완료되지 않은 작업은 자동으로 재개되지 않습니다.",
  "无法确认原会话状态，未停止或归档": "원래 세션 상태를 확인할 수 없습니다. 아무것도 중지되거나 보관되지 않았습니다.",
  "无法确认可停止的原生任务，未停止或归档": "중지할 네이티브 작업을 확인할 수 없습니다. 아무것도 중지되거나 보관되지 않았습니다.",
  "聊天有等待确认的请求，未停止或归档": "채팅에 대기 중인 요청이 있습니다. 아무것도 중지되거나 보관되지 않았습니다.",
  "原运行时连接已变化，未停止或归档": "원래 런타임 연결이 변경되었습니다. 아무것도 중지되거나 보관되지 않았습니다.",
  "停止结果待核对，尚未发送归档请求": "정지 결과는 확인되지 않았습니다. 보관 요청이 전송되지 않았습니다.",
  "置顶设置待同步": "동기화 보류 중인 고정 환경설정",
  "已在此设备保存，等待同步": "이 기기에 저장되었습니다. 동기화 대기 중",
