  "此前归档操作仍待核对；旧记录不会自动清除或重发，请先在原客户端核对": "이전 아카이브 작업이 아직 확인되지 않았습니다. 해당 기록은 자동으로 삭제되거나 재생되지 않습니다. 원래 클라이언트를 먼저 확인하세요.",
  "聊天仍由原 Codex 客户端持有；当前原生连接无法归档，请在持有该聊天的原客户端操作": "원래 Codex 클라이언트는 여전히 이 채팅을 소유하고 있습니다. 거기에 보관하세요. 이 연결은 보관할 수 없습니다.",
  "原 Codex 运行时不支持此归档操作，请在原客户端操作": "원래 Codex 런타임은 이 아카이브 작업을 지원하지 않습니다. 원래 클라이언트를 사용하십시오.",
  "原生客户端已拒绝此次归档操作，请检查原客户端后重试": "네이티브 클라이언트가 이 아카이브 작업을 거부했습니다. 다시 시도하기 전에 원래 클라이언트를 확인하세요.",
  "当前接入尚未确认原生归档和恢复能力": "네이티브 아카이브 및 복원 지원은 이 연결에 대해 확인되지 않았습니다.",
  "聊天或子会话有运行、排队、审批或未知状态，请先在原客户端处理": "이 채팅 또는 하위 항목에 활성, 대기 중, 대기 중 또는 알 수 없는 작업이 있습니다. 원래 클라이언트를 먼저 확인하세요.",
  "聊天或子智能体有运行中的工作，请先在原客户端处理": "이 채팅 또는 하위 에이전트에 진행 중인 작업이 있습니다. 원래 클라이언트를 먼저 확인하세요.",
  "Claude 有待核对的原生写入，请先在原客户端处理": "Claude에 확인되지 않은 네이티브 작업이 있습니다. 원래 클라이언트를 먼저 확인하세요.",
  "原生客户端拒绝归档，操作未发送": "네이티브 클라이언트가 보관을 거부했습니다. 보관 작업이 전송되지 않았습니다.",
