  "此电脑的 Codex Desktop 与 CLI 共用接入；桌面运行时切换会重启桌面应用。": "Codex 데스크톱 및 CLI는 이 컴퓨터에 대한 액세스를 공유합니다. 전환하면 Desktop이 실행 중일 때 다시 시작됩니다.",
  "确认所有任务（包括未在网页显示的任务）已结束，并切换此电脑的 Codex 接入？桌面运行时会重启。": "여기에 표시되지 않은 작업을 포함하여 모든 작업이 종료되었는지 확인하고 이 컴퓨터에서 Codex 액세스를 전환하시겠습니까? 실행 중인 경우 데스크톱이 다시 시작됩니다.",
