  "已结束正在运行的任务": "실행 중인 작업이 종료되었습니다.",
  "同意在需要时重启 Codex Desktop": "필요한 경우 Codex 데스크톱을 다시 시작하도록 허용",
  "请等待当前 Claude Code 任务结束后再发送": "다른 메시지를 보내기 전에 현재 Claude Code 작업이 완료될 때까지 기다리세요.",
  "原项目目录不可用，请在电脑端检查": "원래 프로젝트 디렉터리를 사용할 수 없습니다. 컴퓨터에서 확인해보세요.",
  "有 Claude Code 任务运行或等待确认，请先结束任务再关闭客户端": "Claude Code 작업이 실행 중이거나 승인을 기다리고 있습니다. 클라이언트를 닫기 전에 완료하세요.",
  "Claude Code CLI 暂不支持此发送选项": "이 전송 옵션은 아직 Claude Code CLI에 대해 지원되지 않습니다.",
  "Claude Code 会话": "Claude Code 채팅",
  "Claude Code 会话已关闭，请重新继续": "Claude Code 채팅이 종료되었습니다. 다시 연결하려면 채팅을 계속하세요.",
  "Claude Code 写入结果不明，请检查会话": "Claude Code로의 전송이 확인되지 않았습니다. 계속하기 전에 채팅을 확인하세요.",
  "Claude Code 控制请求未确认，请检查原会话": "Claude Code 작업이 확인되지 않았습니다. 원래 채팅을 확인하세요.",
  "Claude Code 未保留原会话权限模式": "Claude Code는 원래 권한 모드를 유지하지 않았습니다.",
  "Claude Code 未确认权限模式": "Claude Code가 권한 모드를 확인하지 않았습니다.",
  "Claude 会话记录过大，无法读取": "이 Claude 기록 내용이 너무 커서 읽을 수 없습니다.",
  "原生项目登记结果尚未确认，请在电脑 App 完成目录确认后重试同一请求；尚未创建聊天": "프로젝트 등록이 확인되지 않았습니다. 데스크톱 앱에서 폴더를 확인한 후 이 요청을 다시 시도하세요. 생성된 채팅이 없습니다.",
  "原生项目打开结果尚未确认，请检查电脑 App；尚未创建聊天，不会重复登记": "프로젝트 열기가 확인되지 않았습니다. 데스크톱 앱을 확인하세요. 채팅이 생성되지 않았습니다. 등록은 반복되지 않습니다.",
  "请在电脑 App 完成项目目录确认后重试同一请求；尚未创建聊天，不会重复登记": "데스크톱 앱에서 프로젝트 폴더를 확인한 후 이 요청을 다시 시도하세요. 채팅이 생성되지 않았습니다. 등록은 반복되지 않습니다.",
  "请先在电脑 Codex App 添加此 SSH 项目，再重新选择；当前接入尚不支持远程侧栏项目登记": "먼저 Codex 데스크톱에 이 SSH 프로젝트를 추가한 다음 다시 선택하세요. 이 연결은 아직 원격 사이드바 프로젝트를 등록할 수 없습니다.",
  "电脑 App 项目与运行时尚未对应，请检查所用 Codex App 和运行时配置后重试": "데스크톱 프로젝트와 런타임이 아직 일치하지 않습니다. Codex 앱과 런타임 구성을 확인한 후 다시 시도하세요.",
  "此目录对应多个原生项目，请在电脑 App 确认项目归属后重试": "이 폴더는 여러 네이티브 프로젝트와 일치합니다. 다시 시도하기 전에 데스크톱 앱에서 프로젝트를 확인하세요.",
  "聊天已创建但原生项目归属未确认，请检查电脑 App，不要重复创建": "채팅이 생성되었지만 해당 프로젝트가 확인되지 않았습니다. 데스크톱 앱을 확인하세요. 다시 생성하지 마십시오.",
  "聊天已创建但项目归属未持久化确认，请检查电脑 App，不要重复创建": "채팅이 생성되었지만 저장된 프로젝트 할당이 확인되지 않았습니다. 데스크톱 앱을 확인하세요. 다시 생성하지 마십시오.",
  "此 Codex 版本不支持原生项目关联，请更新电脑 Codex App 后重试，或在 App 中添加项目后重新选择": "이 Codex 런타임은 네이티브 프로젝트 할당을 지원하지 않습니다. Codex 데스크톱을 업데이트하거나 앱에 프로젝트를 추가하고 다시 선택하세요.",
  "请选择原会话中可分支的消息": "원래 채팅에서 분기를 지원하는 메시지를 선택하세요.",
  "当前 Claude 接入未提供原生分支接口": "이 Claude 연결은 네이티브 분기를 제공하지 않습니다.",
  "Claude 会话身份或工作目录不一致": "Claude 채팅 ID 또는 작업 디렉터리가 일치하지 않습니다.",
  "不支持的 Claude Code 操作": "이 Claude Code 작업은 지원되지 않습니다.",
  "原 Claude Code 账号配置已变化或不可用": "원래 Claude Code 계정 구성이 변경되었거나 사용할 수 없습니다.",
  "找不到 Claude Code 会话或原账号配置已切换": "Claude Code 채팅을 찾을 수 없거나 원래 계정 구성이 변경되었습니다.",
  "无法确认原会话权限模式，请在电脑端继续": "원래 권한 모드를 알 수 없습니다. 컴퓨터에서 이 채팅을 계속하세요.",
  "此会话已由另一 Claude Code 配置继续，请先结束该连接": "이 채팅은 다른 Claude Code 구성으로 열려 있습니다. 먼저 해당 연결을 닫으십시오.",
  "请先继续这条 Claude Code 会话": "먼저 이 Claude Code 채팅을 계속하세요.",
  "请选择 Claude Code 提供的权限模式": "Claude Code에서 제공하는 권한 모드를 선택하세요.",
  "请选择 Claude Code 提供的模型": "Claude Code에서 제공하는 모델을 선택하세요.",
  "原 Claude Code 会话仍在其他终端运行，请先在原终端结束会话": "이 Claude Code 채팅은 아직 다른 터미널에 열려 있습니다. 계속하기 전에 여기를 닫으세요.",
  "无法确认原 Claude Code 会话是否仍在其他终端运行，请在电脑端检查后重试": "이 Claude Code 채팅이 다른 터미널에 아직 열려 있는지 확인할 수 없습니다. 컴퓨터를 확인하고 다시 시도하세요.",
