  "诊断已更新": "진단이 업데이트되었습니다.",
  "此版本 App 不支持导出文件，请复制摘要或更新 App。": "이 앱 버전은 파일을 내보낼 수 없습니다. 요약을 복사하거나 앱을 업데이트하세요.",
  "继续会话": "대화 계속하기",
  "重建连接": "연결 재구축",
  "桌面连接已失效，建议重建连接。聊天历史和草稿会保留。": "데스크톱 연결을 사용할 수 없습니다. 다시 연결해 주세요. 대화 기록과 초안은 유지됩니다.",
  "桌面执行连接尚未恢复，建议点击“重建连接”。操作未发送。": "데스크톱 실행 연결을 사용할 수 없습니다. 연결을 다시 구축해 보세요. 아무것도 전송되지 않았습니다.",
  "桌面执行连接不可用，可点击“重建连接”恢复；未确认操作不会自动重发。": "데스크톱 실행 연결을 사용할 수 없습니다. 연결을 다시 구축해 보세요. 확인되지 않은 작업은 자동으로 다시 전송되지 않습니다.",
  "桌面连接检查未完成，请稍后重试。": "데스크톱 연결 확인이 완료되지 않았습니다. 잠시 후 다시 시도하세요.",
  "此会话不使用桌面连接，请使用继续会话。": "이 채팅은 데스크톱 연결을 사용하지 않습니다. 계속 채팅을 사용하세요.",
  "可先阅读聊天历史；继续时将恢复原 Claude Code 会话。": "저장된 기록을 읽거나 이 Claude Code 채팅을 계속 재개하세요.",
  "可先阅读聊天历史；继续时将恢复原会话。": "저장된 기록을 읽거나 원래 채팅을 계속 재개하세요.",
  "CLI 会话尚未恢复；操作未发送，请重试继续会话。": "CLI 채팅이 재개되지 않았습니다. 아무것도 전송되지 않았습니다. 다시 채팅을 계속해 보세요.",
  "正在等待原 Codex App 会话快照；未启动 CLI 后台服务。": "원래 Codex 앱 채팅을 기다리고 있습니다. CLI 데몬이 시작되지 않았습니다.",
  "现有 Codex App 连接与此会话不匹配，未连接": "현재 Codex 앱 연결이 이 채팅과 일치하지 않습니다. 연결되지 않았습니다.",
  "可先阅读聊天历史；继续时将连接或恢复原 CLI 会话。": "먼저 채팅 기록을 읽어보세요. 원래 CLI 세션에 계속 연결하거나 재개합니다.",
  "CLI 聊天历史可阅读；当前无法继续此会话。": "CLI 채팅 기록을 사용할 수 있습니다. 지금은 이 채팅을 계속할 수 없습니다.",
  "未找到可用的 Codex CLI 后台服务或已安装的服务包；请先在电脑上安装或更新 Codex CLI，并运行一次。": "Codex CLI 데몬 또는 설치된 데몬 패키지를 찾을 수 없습니다. 컴퓨터에 Codex CLI를 설치하거나 업데이트하고 한 번 실행하세요.",
  "其他来源": "기타 소스",
  "已保存的历史可阅读；当前来源未提供远程控制。": "저장된 이력을 보실 수 있습니다. 이 소스에는 원격 제어를 사용할 수 없습니다.",
  "已登录": "로그인됨",
  "自定义服务": "맞춤 서비스",
  "向 HTTPS Webhook 服务发送通知。": "HTTPS 웹훅 서비스에 알림을 보냅니다.",
  "服务类型": "서비스 유형",
  "自动识别": "자동 감지",
  "通用 Webhook": "일반 웹훅",
