  "按地址自动识别服务类型，并选择相应默认模板。": "해당 주소에서 서비스를 감지하고 기본 템플릿을 사용합니다.",
  "已识别飞书地址；默认模板自动使用飞书格式。": "Feishu 주소가 감지되었습니다. 기본 템플릿은 자동으로 Feishu 형식을 사용합니다.",
  "自定义 HTTPS Webhook，可编辑 JSON 正文。": "편집 가능한 JSON 본문이 있는 사용자 정의 HTTPS 웹훅입니다.",
  "飞书群机器人地址；签名密钥可选。": "Feishu 그룹 봇 엔드포인트; 서명 비밀은 선택 사항입니다.",
  "钉钉群机器人地址；签名密钥可选。": "DingTalk 그룹 봇 엔드포인트; 서명 비밀은 선택 사항입니다.",
  "Discord Webhook 地址；content 最多 2000 字符。": "Discord 웹훅 엔드포인트; 내용은 2,000자로 제한됩니다.",
  "Telegram Bot API sendMessage 地址；在 JSON 中填写 chat_id，text 最多 4096 字符。": "Telegram 봇 API sendMessage 끝점; JSON에 chat_id를 입력하세요. 텍스트는 4,096자로 제한됩니다.",
  "飞书群机器人地址形如 open.feishu.cn/open-apis/bot/v2/hook/…；签名可选。": "Feishu 봇 엔드포인트: open.feishu.cn/open-apis/bot/v2/hook/… 서명은 선택 사항입니다.",
  "钉钉群机器人地址形如 oapi.dingtalk.com/robot/send?access_token=…；签名可选。": "DingTalk 봇 엔드포인트: oapi.dingtalk.com/robot/send?access_token=… 서명은 선택 사항입니다.",
  "Discord 地址形如 discord.com/api/webhooks/…；content 最多 2000 字符。": "Discord 엔드포인트: discord.com/api/webhooks/… 콘텐츠 제한은 2,000자입니다.",
  "Telegram 地址形如 api.telegram.org/bot…/sendMessage；在 JSON 中填写 chat_id，text 最多 4096 字符。": "Telegram 엔드포인트: api.telegram.org/bot…/sendMessage. JSON에 chat_id를 입력하세요. 텍스트 제한은 4,096자입니다.",
  "签名仅适用于飞书和钉钉机器人。": "서명은 Feishu 및 DingTalk 봇에만 사용할 수 있습니다.",
