  "列表包含当前接入模型及历史模型，历史模型的可用性需由客户端确认。": "현재 연결에서 제공하는 모델과 이전에 사용한 모델이 표시됩니다. 이전 모델을 계속 사용할 수 있는지는 연결된 앱에서 확인해야 합니다.",
  "客户端尚未提供当前可选模型，历史模型仅供查看": "클라이언트가 선택 가능한 모델을 제공하지 않았습니다. 과거 모델은 참조용으로만 표시됩니다.",
  "接入信息读取超时": "연결 세부정보 시간이 초과되었습니다.",
  "请输入首条消息，Claude 将创建会话并发送此消息": "첫 번째 메시지를 입력하세요. Claude가 대화를 생성하여 보냅니다.",
  "图片附件格式无效": "잘못된 이미지 첨부 형식",
  "Cowork 未提供补充当前任务接口，请使用普通发送": "Cowork는 현재 작업 조정을 지원하지 않습니다. 대신 새 메시지를 보내세요.",
