  "当前客户端未提供此思考强度设置": "이 클라이언트는 해당 추론 강도 설정을 제공하지 않습니다.",
  "桌面未确认模型设置，请刷新后检查": "데스크톱 앱이 모델 설정을 확인하지 않았습니다. 확인하려면 새로고침하세요.",
  "请选择当前客户端提供的权限选项": "이 클라이언트가 제공한 권한 옵션을 선택하세요.",
  "Claude 未确认权限设置，请在桌面检查组织策略": "Claude가 권한 설정을 확인하지 않았습니다. 데스크톱 앱에서 조직 정책을 확인하세요.",
