  "允许编辑文件，其他操作沿用 Claude 的确认规则": "파일 편집을 허용합니다. 다른 작업은 Claude 승인 규칙을 따릅니다.",
  "先制定计划，操作权限由 Claude 决定": "먼저 계획을 세우십시오. Claude는 작업 권한을 결정합니다.",
  "技能已不可用，请刷新后选择": "해당 스킬을 더 이상 사용할 수 없습니다. 새로고침하고 다시 선택하세요.",
