  "登录已失效，请重新登录后继续下载。": "세션이 만료되었습니다. 재개하려면 다시 로그인하세요.",
  "下载失败，请检查连接后重试。": "다운로드에 실패했습니다. 연결을 확인하고 다시 시도하세요.",
