  "手动连接": "수동으로 연결",
  "需要手动初始化": "수동 초기화 필요",
  "正在准备后台连接…": "백그라운드 연결 준비 중…",
  "正在连接 Claude": "Claude에 연결 중",
  "请手动连接 Claude；初始化会短暂使用前台窗口，之后在后台保持连接。": "Claude를 수동으로 연결하세요. 초기화에서는 전경 창을 잠시 사용한 다음 연결이 배경에 유지됩니다.",
  "已选择，启动网关后在后台等待连接": "선택된. 게이트웨이가 시작될 때 백그라운드에서 연결을 기다립니다.",
  "选择需要接入的应用；Claude 首次连接需手动初始化，之后在后台重连。": "연결할 앱을 선택하세요. Claude를 수동으로 한 번 초기화하십시오. 나중에 다시 연결되면 백그라운드에서 발생합니다.",
  "重启 Claude 会断开当前会话。请先结束任务并保存工作，再确认重启并接入。": "Claude를 다시 시작하면 현재 세션의 연결이 끊어집니다. 모든 작업을 완료하고 다시 시작을 확인하기 전에 작업 내용을 저장하세요.",
  "Claude 有任务运行或等待确认，请先结束任务再重启": "Claude에는 실행 중인 작업이 있거나 승인이 보류 중입니다. 다시 시작하기 전에 완료하세요.",
