  "此系统暂未提供 Claude 自动连接组件": "이 플랫폼에서는 아직 자동 Claude 연결을 사용할 수 없습니다.",
  "正在自动连接 Claude": "Claude에 자동으로 연결",
  "Claude 连接未就绪": "Claude 연결이 준비되지 않았습니다.",
  "未找到 Claude 数据目录，请重新扫描": "Claude의 데이터 디렉터리를 찾을 수 없습니다. 다시 스캔하세요.",
  "请在 Claude 的帮助菜单中启用开发者模式，然后重试连接": "Claude의 도움말 메뉴에서 개발자 모드를 활성화한 후 다시 연결해 보세요.",
  "请在 Claude 中确认开发者模式": "Claude에서 개발자 모드 확인",
  "请确认 Claude 的开发者模式提示，完成后会继续连接": "계속 연결하려면 Claude의 개발자 모드 프롬프트를 확인하세요.",
  "正在连接 Claude，请暂时保持 Console 焦点，按 Esc 可取消": "Claude에 연결 중입니다. 지금은 콘솔에 집중하세요. 취소하려면 Esc를 누르세요.",
