  "未收到 Claude 连接确认，请检查登录和目录信任后重试": "Claude에서 연결 확인이 없습니다. 로그인 및 디렉터리 신뢰를 확인한 후 다시 시도하세요.",
  "Claude 自动连接未完成，请重试": "자동 Claude 연결이 완료되지 않았습니다. 다시 시도해 보세요.",
  "已取消 Claude 连接": "Claude 연결이 취소되었습니다.",
  "连接脚本格式不支持，请重新构建应用": "지원되지 않는 커넥터 스크립트 형식입니다. 앱을 다시 빌드합니다.",
  "缺少 Claude 自动连接组件，请重新构建或安装网关 App": "Claude 커넥터 구성요소가 누락되었습니다. 게이트웨이 앱을 다시 빌드하거나 다시 설치하세요.",
  "Claude 自动连接超时，请重试": "Claude 연결 시간이 초과되었습니다. 다시 시도해 보세요.",
  "Claude 连接组件未返回有效状态": "Claude 커넥터가 유효한 상태를 반환하지 않았습니다.",
  "请在 Claude Code 中确认连接目录信任，然后重新连接": "Claude Code의 연결 디렉터리를 신뢰한 다음 다시 연결하세요.",
  "Claude 自动连接失败": "자동 Claude 연결 실패",
  "连接脚本已输入，正在等待 Claude 确认": "커넥터가 입력되었습니다. Claude가 확인되기를 기다리는 중",
