  "无法确认唯一的 Claude 主进程，请检查桌面窗口": "단일 Claude 기본 프로세스를 식별할 수 없습니다. 바탕화면 창을 확인해보세요.",
  "目标不是已发现的 Claude Desktop": "대상은 검색된 Claude 데스크톱 앱이 아닙니다.",
  "焦点已离开 Claude，自动连接已停止，请重试": "초점이 Claude에서 멀어졌습니다. 자동 연결이 중지되었습니다. 다시 시도해 보세요.",
