  "Claude Console 输入焦点已改变，自动连接已停止": "Claude 콘솔 입력 포커스가 변경되었습니다. 자동 연결이 중지되었습니다",
  "无法创建键盘事件": "키보드 이벤트를 생성할 수 없습니다",
  "未找到 Claude Console，请在结束当前任务后重启 Claude 再连接": "Claude 콘솔을 찾을 수 없습니다. 현재 작업을 완료한 다음 Claude를 다시 시작하고 다시 연결하세요.",
  "未找到 Claude Console，请确认开发者工具窗口可用后重试": "Claude 콘솔을 찾을 수 없습니다. 개발자 도구를 사용할 수 있는지 확인한 후 다시 시도하세요.",
  "无法创建 Console 提交事件，连接脚本已保留": "콘솔에 제출할 수 없습니다. 커넥터 스크립트는 보존되었습니다.",
  "未确认 Console 已提交，已停止自动操作；请检查 Console 和连接状态后重试": "콘솔 제출을 확인할 수 없습니다. 자동 설정이 중지되었습니다. 다시 시도하기 전에 콘솔과 연결 상태를 확인하세요.",
  "Claude 已连接，但未能关闭开发者工具窗口": "Claude가 연결되었지만 개발자 도구 창을 닫을 수 없습니다.",
  "Console 内容未完整到达，未执行连接脚本，请重试": "전체 커넥터가 콘솔에 도달하지 못하고 실행되지 않았습니다. 다시 시도해 보세요.",
  "Console 无法核验完整内容，未执行连接脚本，请重试": "전체 콘솔 입력을 확인할 수 없습니다. 커넥터가 실행되지 않았습니다. 다시 시도해 보세요.",
  "连接脚本格式无效": "잘못된 커넥터 스크립트 형식",
  "Console 中已有未提交内容，已保留，请处理后重试连接": "콘솔에 완료되지 않은 초안이 포함되어 있습니다. 그것은 보존되었습니다. 다시 연결하기 전에 완료하세요.",
  "Console 拒绝输入连接脚本": "콘솔이 커넥터 입력을 거부했습니다.",
  "请在系统设置中允许 Claude 连接组件使用辅助功能，授权后会继续连接": "Claude 커넥터가 시스템 설정에서 접근성을 사용하도록 허용합니다. 권한이 부여된 후에 연결이 계속됩니다.",
  "辅助功能已授权": "접근성 권한이 부여됨",
  "连接组件参数无效": "잘못된 커넥터 인수",
  "已恢复此前的 Harness 接入": "이전 Harness 연결이 복구되었습니다.",
  "已有 Harness 接入无法验证，尚未修改配置": "기존 Harness 연결을 확인할 수 없습니다. 해당 구성은 변경되지 않았습니다.",
  "已有 Harness 接入无法验证，请重新扫描": "저장된 Harness 연결을 확인할 수 없습니다. 다시 스캔하세요.",
  "此前接入的操作记录不可用，请重新扫描": "이전 연결의 작업 기록을 확인할 수 없습니다. 다시 스캔하세요.",
  "Claude 已连接": "Claude가 연결됨",
  "Claude 已连接，但关闭开发者工具失败": "Claude가 연결되었지만 개발자 도구를 닫을 수 없습니다.",
  "Claude 已连接，开发者工具尚未关闭": "Claude가 연결되었습니다. 개발자 도구가 아직 열려 있습니다.",
  "Claude 窗口尚未准备好": "Claude 창이 아직 준비되지 않았습니다.",
  "Claude 连接组件未能完成操作，请重试": "Claude 커넥터가 작업을 완료할 수 없습니다. 다시 시도해 보세요.",
  "Console 本段输入未完整到达，未执行；再次连接会自动恢复连接脚本": "콘솔이 전체 커넥터를 수신하지 못하여 실행되지 않았습니다. 복원하려면 다시 연결하세요.",
  "Console 输入焦点已改变，自动输入已取消": "콘솔 포커스가 변경되었습니다. 자동 입력이 취소되었습니다.",
  "Windows 拒绝键盘输入，请检查 Claude 与助手的权限是否一致": "Windows가 키보드 입력을 거부했습니다. Claude와 커넥터가 동일한 권한으로 실행되는지 확인하세요.",
  "已取消键盘连接，点击 Claude 标题选择启动可重试": "키보드 연결이 취소되었습니다. 다시 시도하려면 Claude를 다시 연결하세요.",
  "找不到 Claude Console 输入框，请确认已允许开发者工具后通过标题重试": "Claude 콘솔 입력을 찾을 수 없습니다. 개발자 도구를 활성화한 후 다시 연결하세요.",
  "无法核对 Console 内容，已停止输入": "콘솔 콘텐츠를 확인할 수 없습니다. 입력이 중지되었습니다",
  "无法读取 Claude 窗口，请检查运行权限": "Claude 창을 읽을 수 없습니다. 애플리케이션 권한을 확인하세요.",
  "目标不是 Claude": "대상이 Claude가 아닙니다.",
  "键盘连接参数无效": "잘못된 키보드 커넥터 인수",
  "Claude 尚未退出，请在电脑上关闭后重试；尚未强制结束进程": "Claude가 종료되지 않았습니다. 컴퓨터에서 닫고 다시 시도하세요. 강제 종료가 아니었습니다.",
  "当前使用已有 Harness 接入，未移除原接入配置": "기존 Harness 연결을 사용합니다. 원래 구성은 제거되지 않았습니다.",
  "接入的操作记录正被另一网关占用，请停止旧网关后重试": "다른 게이트웨이가 연결 작업 기록을 사용하고 있습니다. 기존 게이트웨이를 중지하고 다시 시도하세요.",
  "重启 Harness 会断开当前会话。请先在 Harness 中结束所有任务并保存工作，再确认重启并接入。": "Harness를 다시 시작하면 현재 세션의 연결이 끊어집니다. 모든 작업을 완료하고 다시 시작을 확인하기 전에 Harness에 작업을 저장하세요.",
  "尚未安装此客户端": "이 클라이언트는 설치되지 않았습니다.",
  "请先打开 Harness 完成首次设置，再重新扫描": "Harness를 열고 초기 설정을 마친 후 다시 스캔하세요.",
  "请结束当前任务后重启 Harness 完成接入": "현재 작업을 완료하고 Harness를 다시 시작하여 연결하세요.",
  "正在等待 Harness 连接": "Harness가 연결되기를 기다리는 중",
  "Harness 有任务运行或等待确认，请先结束任务再重启": "Harness에는 실행 중인 작업이 있거나 승인이 보류 중입니다. 다시 시작하기 전에 완료하세요.",
  "不支持的本机管理操作": "지원되지 않는 로컬 관리 작업",
  "请等待账号操作完成后再启动网关": "게이트웨이를 시작하기 전에 계정 작업이 완료될 때까지 기다리십시오.",
  "网关正在启动，请稍后重试": "게이트웨이가 시작 중입니다. 잠시 후 다시 시도하세요.",
  "请重新启动网关以启用客户端管理": "클라이언트 관리를 활성화하려면 게이트웨이를 다시 시작하세요.",
  "本机管理已关闭": "현지 관리가 종료되었습니다.",
