  "Claude 已连接；开发者工具未自动关闭，请手动关闭": "Claude가 연결되었습니다. 개발자 도구 창을 수동으로 닫아주세요.",
  "Claude 连接已中断，请点击连接重试": "Claude 연결이 끊어졌습니다. 다시 시도하려면 연결을 선택하세요.",
  "Claude 自动连接未完成，请点击连接重试": "Claude가 연결을 완료할 수 없습니다. 다시 시도하려면 연결을 선택하세요.",
  "Claude 窗口已改变，自动连接已停止，请重试": "Claude 창이 변경되었습니다. 자동 연결이 중지되었습니다. 다시 시도해 주세요.",
  "检测到残留 Harness 后台实例且无法核对任务状态，请在电脑端退出 Harness 后重试": "남은 Harness 백그라운드 프로세스가 발견되었으며 해당 작업을 확인할 수 없습니다. 컴퓨터에서 Harness를 종료한 후 다시 시도하십시오.",
  "检测到多个或无法识别的 Harness 实例，请在电脑端检查后重试": "여러 개의 또는 인식할 수 없는 Harness 인스턴스가 발견되었습니다. 다시 시도하기 전에 컴퓨터에서 확인하세요.",
  "Harness 已打开，请完成首次设置后点击接入": "Harness가 열려 있습니다. 초기 설정을 완료한 다음 연결을 선택합니다.",
