  "选择需要接入的应用；启动网关后自动打开并检查登录状态。": "연결할 앱을 선택하세요. 게이트웨이가 시작되면 로그인 상태를 열고 확인합니다.",
  "已发现客户端，启用后随网关启动并接入": "앱을 찾았습니다. 게이트웨이가 시작될 때 열고 연결하려면 선택하세요.",
