  "正在交接桌面更新，请稍后再操作": "데스크톱 업데이트를 전달하는 중입니다. 잠시 후 다시 시도하세요.",
  "此账号已添加，请先删除旧档案再重新授权": "이 계정은 이미 저장되어 있습니다. 다시 인증하기 전에 이전 항목을 제거하세요.",
