  "请填写桌面程序的完整路径": "데스크톱 앱의 전체 경로를 입력하세요.",
  "请确认恢复原接入并重启桌面应用": "이전 연결 복원을 확인하고 데스크톱 앱을 다시 시작하세요.",
  "请确认所有桌面任务已结束，并同意重启 Codex 桌面应用": "모든 데스크톱 작업이 완료되었는지 확인하고 Codex 데스크톱 앱을 다시 시작하도록 허용합니다.",
  "请确认所有桌面任务已结束，并授权打开原生更新器": "모든 데스크톱 작업이 완료되었는지 확인하고 앱 자체 업데이터가 열리도록 허용합니다.",
  "请等待账号切换完成后再停止网关": "게이트웨이를 중지하기 전에 계정 전환이 완료될 때까지 기다리세요.",
  "请选择自有服务器连接。": "자체 호스팅 서버 연결을 선택합니다.",
