  "账号服务超时或已断开": "계정 서비스 시간이 초과되었거나 연결이 끊어졌습니다.",
  "账号标识无效": "잘못된 계정 ID.",
  "账号目录不能是符号链接": "계정 디렉터리는 심볼릭 링크일 수 없습니다.",
  "账号身份不匹配": "계정 ID가 일치하지 않습니다.",
  "账号身份已变化": "계정 ID가 변경되었습니다.",
  "账号身份未生效": "계정 ID가 적용되지 않았습니다.",
  "运行时拒绝账号或配置操作，请检查登录及工作区限制": "런타임이 계정 또는 구성 작업을 거부했습니다. 로그인 및 작업 공간 제한 사항을 확인하세요.",
  "连接凭据格式不正确": "연결 자격 증명 형식이 잘못되었습니다.",
  "账号重置请求包含不支持的字段": "계정 재설정 요청에 지원되지 않는 필드가 포함되어 있습니다.",
  "查看并使用所选账号的重置卡": "선택한 계정의 재설정 크레딧 보기 및 사용",
  "PushPlus 测试失败，请检查服务地址、认证和网络": "PushPlus 테스트가 실패했습니다. 서비스 주소, 인증, 네트워크를 확인하세요.",
  "未收到所选文件，请重新选择。": "선택한 파일이 수신되지 않았습니다. 파일을 다시 선택하세요.",
  "无法读取所选文件，请从系统文件选择器重新选择。": "선택한 파일을 읽을 수 없습니다. 시스템 파일 선택기를 사용하여 다시 선택하십시오.",
  "已保存的接入": "저장된 연결",
  "此手机已绑定，可在电脑网关的“登录设备”中解除绑定。": "이 전화는 연결되어 있습니다. 데스크톱 게이트웨이의 로그인된 장치에서 연결을 해제하세요.",
