  "启动网关后检查客户端与账号配置。": "클라이언트 및 계정 설정을 확인하려면 게이트웨이를 시작하세요.",
  "桌面会话": "데스크톱 세션",
  "Harness 官方 Web": "Harness 공식 웹사이트",
  "Harness 官方 Web ↗": "Harness 공식 웹사이트 ↗",
