  "继续桌面已有会话，沿用桌面模型与项目配置。首次接入后需要重新打开 Harness。": "모델 및 프로젝트 설정으로 기존 데스크톱 세션을 계속합니다. 첫 번째 설정 후 Harness를 다시 시작하십시오.",
