  "只能忽略发送结果未确认的记录": "확인되지 않은 전송 기록만 무시할 수 있습니다.",
  "已忽略未确认记录": "확인되지 않은 기록은 무시됩니다.",
  "这条未确认记录已忽略，请刷新后重新编辑消息。": "이 확인되지 않은 기록은 무시되었습니다. 다시 보내기 전에 메시지를 새로 고치고 편집하세요.",
  "上次发送结果尚未确认，请检查聊天记录或先处理未确认记录。": "이전 전송이 아직 확인되지 않았습니다. 채팅 기록을 확인하거나 확인되지 않은 기록을 먼저 해결하세요.",
  "在线指引": "온라인 가이드",
  "Skill 加载失败，请点击刷新重试": "스킬을 로드할 수 없습니다. 다시 시도하려면 새로 고침을 클릭하세요.",
  "Skill 链接目标已变化，请刷新列表后重新选择": "스킬링크 대상이 변경되었습니다. 목록을 새로 고치고 다시 선택하세요.",
  "此聊天保留了原提供商，请切回对应接入或新建聊天": "이 채팅은 이전 공급자를 유지합니다. 다시 전환하거나 새 채팅을 시작하세요.",
  "有排队消息或发送结果未确认，请先处理后再切换": "전환하기 전에 대기 중인 메시지와 확인되지 않은 제출을 해결하세요.",
  "有任务运行或等待确认，请先在桌面结束任务再切换": "전환하기 전에 실행 중인 작업과 보류 중인 승인을 완료하세요.",
  "请先在桌面端指定 Codex 桌面程序路径": "먼저 데스크톱 앱에서 Codex 데스크톱 실행 파일을 선택하세요.",
  "切换未执行，请检查账号登录、配置限制和桌面程序路径": "전환이 수행되지 않았습니다. 로그인, 구성 제한 및 데스크톱 실행 파일을 확인하세요.",
  "切换未完成，已恢复原接入；请检查桌面程序或重新登录": "전환에 실패했습니다. 이전 계정이 복원되었습니다. 데스크톱 앱을 확인하거나 다시 로그인하세요.",
  "自动恢复未完成，请在桌面端恢复原接入": "자동 복구에 실패했습니다. 데스크톱 앱에서 이전 계정을 복원하세요.",
  "上次切换中断，请在桌面端恢复原接入": "이전 스위치가 중단되었습니다. 데스크톱 앱에서 이전 계정을 복원하세요.",
  "请先切换到其他接入，再删除此账号": "이 계정을 삭제하기 전에 다른 계정으로 전환하세요.",
  "请先切换到其他接入，再修改此 API": "이 API를 편집하기 전에 다른 계정으로 전환하세요.",
  "请先切换到其他接入，再重新登录此账号": "다시 로그인하기 전에 다른 계정으로 전환하세요.",
  "请先完成或取消正在进行的登录": "먼저 대기 중인 로그인을 완료하거나 취소하세요.",
  "PushPlus 通知": "PushPlus 알림",
  "局域网访问范围": "LAN 액세스 범위",
  "自动内网地址": "자동 LAN 주소",
  "仅选中的网卡": "선택된 어댑터만",
  "自动模式只发布非虚拟网卡上的私有内网地址；Parallels、WSL、Docker 和 VPN 虚拟网卡不会出现在通知里。选择网卡可自定义范围，同一网卡的 IP 变化会自动跟随。": "자동 모드는 비가상 어댑터에만 개인 LAN 주소를 게시합니다. Parallels, WSL, Docker 및 VPN 가상 어댑터는 알림에 표시되지 않습니다. 사용자 정의 범위에 대한 어댑터를 선택하면 선택한 어댑터의 주소 변경 사항이 자동으로 적용됩니다.",
  "允许本机网页访问（127.0.0.1 / localhost）": "로컬 브라우저 접근 허용(127.0.0.1 / localhost)",
  "关闭后隐藏本机地址并拒绝本机网页访问；桌面状态检查和 HTTPS 隧道仍保留内部回环连接。": "끄면 로컬 URL이 숨겨지고 로컬 브라우저 액세스가 차단됩니다. 데스크톱 상태 확인 및 HTTPS 터널은 내부 루프백 연결을 유지합니다.",
  "项目主页 ↗": "프로젝트 홈 ↗",
  "反馈问题 · Issue ↗": "문제 신고 ↗",
  "贡献代码 · PR ↗": "PR 기부 ↗",
  "当前不可用": "현재는 이용할 수 없습니다",
  "未发现可用的局域网网卡": "LAN 어댑터를 찾을 수 없습니다.",
  "请选择有效的局域网 IPv4 地址": "유효한 LAN IPv4 주소를 선택하세요.",
  "所选网卡地址不可用或端口已被占用，请检查网卡与端口；不会自动开放其他网卡": "선택한 어댑터 주소를 사용할 수 없거나 해당 포트가 사용 중입니다. 어댑터와 포트를 확인하세요. 다른 어댑터는 자동으로 열리지 않습니다.",
  "本机网页访问已关闭": "로컬 브라우저 액세스가 비활성화되었습니다.",
  "仅允许本机状态检查": "로컬 상태 확인만 허용됩니다.",
  "使用微信登录 PushPlus、关注服务号并完成实名认证，复制个人资料中的 Token。勾选启用并保存后发送测试通知，再到设置中选择全会话通知，或在聊天提醒中单独调整。": "WeChat으로 PushPlus에 로그인하고 해당 서비스 계정을 팔로우한 후 실명 확인을 완료하고 프로필에서 토큰을 복사하세요. 채널을 활성화 및 저장하고 테스트 알림을 보낸 다음 설정에서 전체 알림을 선택하거나 개별 채팅에 대한 알림을 조정하세요.",
  "PushPlus 需付费实名认证，最低 3.9 元；认证后可使用基础额度，无需另购会员。费用以官方页面为准。": "PushPlus에는 CNY 3.90부터 유료 실명 확인이 필요합니다. 인증된 사용자는 회원가입 없이도 기본수당을 사용할 수 있습니다. 현재 가격은 공식 페이지를 확인하세요.",
  "微信渠道普通实名用户每天 200 次请求、每分钟 5 次；相同内容每小时最多 3 条，失败请求也计入额度。超限可能暂停推送。": "일반 검증된 사용자의 경우 WeChat 채널은 하루에 200개, 분당 5개의 요청을 허용하며 시간당 최대 3개의 동일한 메시지를 허용합니다. 실패한 요청도 포함됩니다. 한도를 초과하면 전송이 중단될 수 있습니다.",
  "PushPlus 官网与 Token ↗": "PushPlus 웹사이트 및 토큰 ↗",
  "实名认证与费用 ↗": "검증 및 가격 ↗",
  "额度与频率限制 ↗": "사용 한도 및 비율 제한 ↗",
  "发送 PushPlus 测试通知": "PushPlus 테스트 알림 보내기",
  "修改聊天名称": "채팅 이름 바꾸기",
  "聊天名称已修改": "채팅 이름이 변경되었습니다.",
  "测试已保存的配置": "저장된 설정 테스트",
  "在 PushPlus 官网获取 Token。保存后，在需要提醒的聊天中开启提醒。": "PushPlus 웹사이트에서 토큰을 받으세요. 저장한 후 팔로우하려는 각 채팅에서 알림을 활성화하세요.",
  "请先配置并开启 PushPlus、Bark 或 ntfy 通知": "먼저 PushPlus, Bark 또는 ntfy를 구성하고 활성화합니다.",
  "PushPlus Token 格式不正确": "잘못된 PushPlus 토큰",
  "开启 PushPlus 前请填写 Token": "PushPlus를 활성화하기 전에 토큰을 입력하세요.",
  "请先配置 PushPlus Token": "먼저 PushPlus 토큰을 구성하세요.",
  "PushPlus 未接受通知，请检查 Token 和网络": "PushPlus가 알림을 거부했습니다. 토큰과 네트워크를 확인하세요.",
  "PushPlus 测试失败，请检查 Token 和网络": "PushPlus 테스트가 실패했습니다. 토큰과 네트워크를 확인하세요.",
