  "正在加载交互图表…": "시각화 로드 중…",
  "交互图表加载失败，请重试": "시각화를 로드하지 못했습니다. 다시 해 보다.",
  "交互状态保存失败": "상호작용 상태를 저장할 수 없습니다.",
  "此聊天暂时无法读取交互图表": "이 채팅에서는 시각화를 사용할 수 없습니다.",
  "可视化文件未被此聊天引用": "이 시각화는 이 채팅에서 참조되지 않습니다.",
  "可视化地址无效": "잘못된 시각화 주소",
  "可视化内容超过 1 MB": "시각화가 1MiB를 초과합니다.",
