  "HTML 预览无法加载，请查看源代码或下载文件": "HTML 미리보기를 로드할 수 없습니다. 소스를 보거나 파일을 다운로드하세요.",
  "预览": "시사",
  "阅读": "독서",
  "源代码": "소스 코드",
  "上一页": "이전 페이지",
  "下一页": "다음 페이지",
  "缩小": "축소",
  "放大": "확대",
  "正在打开 PDF…": "PDF 여는 중…",
  "正在渲染 PDF…": "PDF 렌더링 중...",
  "PDF 超过在线预览或当前下载限额，请下载后打开。": "이 PDF는 미리보기 또는 현재 다운로드 제한을 초과합니다. 다운로드하여 열어보세요.",
  "此 PDF 已加密，请下载后使用其他应用打开。": "이 PDF는 암호화되어 있습니다. 다운로드하고 다른 앱에서 열어보세요.",
  "PDF 文件已损坏或格式无效，请下载后检查。": "이 PDF가 손상되었거나 유효하지 않습니다. 파일을 검사하려면 다운로드하세요.",
  "PDF 预览失败，请下载后使用其他应用打开。": "PDF 미리보기가 실패했습니다. 다운로드하고 다른 앱에서 열어보세요.",
  "已复制": "복사됨",
  "复制内容": "텍스트 복사",
  "编辑消息": "메시지 편집",
  "编辑并重新发送": "수정하고 다시 보내기",
  "编辑并新建分支": "새 지점에서 편집",
  "从这里分支": "여기에서 분기",
  "来源会话：": "소스 채팅:",
  "浏览器限制自动复制，请长按选中文本复制，或使用系统复制快捷键。": "귀하의 브라우저가 자동 복사를 차단했습니다. 텍스트를 선택하고 시스템 복사 작업이나 키보드 단축키를 사용합니다.",
  "将替换这条消息并重新生成回答。已经执行的文件修改和命令不会撤销。": "이 메시지를 바꾸고 새 응답을 생성하세요. 이전에 실행한 파일 변경 사항과 명령은 그대로 유지됩니다.",
  "保留截至这一轮的上下文，创建后等待你继续输入。新会话与原会话共享工作目录。": "이번 차례까지 기록을 유지하고 다음 메시지를 기다리세요. 두 채팅 모두 동일한 작업 디렉터리를 공유합니다.",
  "保留原会话，在新分支中修改并重新生成这一轮。新会话与原会话共享工作目录。": "원래 채팅을 유지하고 새 분기에서 편집 내용을 사용하여 이번 턴을 다시 생성하세요. 두 채팅 모두 작업 디렉터리를 공유합니다.",
  "聊天已切换，请重新选择消息": "채팅이 바뀌었습니다. 메시지를 다시 선택하세요.",
  "消息内容已变化，请重新打开编辑": "메시지가 변경되었습니다. 다시 열어보세요.",
  "消息位置已变化，请刷新后重试": "대화가 바뀌었습니다. 새로고침하고 다시 시도하세요.",
  "读取完整正文失败，请重试": "전체 텍스트를 로드할 수 없습니다. 다시 시도해 보세요.",
  "操作结果尚未确认，请先检查聊天记录。再次提交不会重复执行。": "결과는 확인되지 않았습니다. 먼저 채팅 기록을 확인하세요. 다시 제출하면 작업이 반복되지 않습니다.",
  "分支已创建，可在聊天列表查看。": "브랜치가 생성되었으며 채팅 목록에서 사용할 수 있습니다.",
  "分支已创建，修改尚未发送。请连接后编辑最后一条消息。": "분기가 생성되었지만 편집 내용이 전송되지 않았습니다. 계속하려면 마지막 메시지를 연결하고 편집하세요.",
  "已创建分支": "지점이 생성되었습니다.",
  "已在分支中重新发送": "새 지점에서 재전송",
  "已重新发送": "메시지 재전송",
  "正在提交…": "제출 중…",
  "消息操作无效": "잘못된 메시지 작업",
  "同一操作标识不能用于不同内容": "ID 작업은 다른 콘텐츠에 재사용할 수 없습니다.",
  "此消息不支持该操作": "이 메시지에는 이 작업을 수행할 수 없습니다.",
  "请先停止当前任务，再编辑或分支": "편집하거나 분기하기 전에 현재 회전을 중지하세요.",
  "只有最近一条消息可原地编辑，请使用编辑并新建分支": "여기에서는 최신 메시지만 편집할 수 있습니다. 새 지점에서 편집을 사용하십시오.",
  "尚未取得原会话的模型配置，请重新连接": "원래 모델 설정을 사용할 수 없습니다. 먼저 다시 연결하세요.",
  "此 Codex 版本暂不支持安全分支，请更新电脑 Codex App": "안전한 대화 분기를 사용하려면 데스크톱 Codex 앱을 업데이트하세요.",
  "分支结果无效，请检查桌面聊天列表": "잘못된 분기 결과입니다. 데스크톱 채팅 목록을 확인하세요.",
  "分支位置未确认，请检查桌面聊天列表，不要重复创建": "지점 위치는 확인되지 않았습니다. 다시 시도하기 전에 데스크톱 채팅 목록을 확인하세요.",
  "分支模型提供商不一致，请检查桌面聊天列表": "지점 공급자가 일치하지 않습니다. 데스크톱 채팅 목록을 확인하세요.",
  "目标进度": "목표 진행",
  "隐藏目标栏": "목표 패널 숨기기",
  "工作模式": "작업 모드",
  "默认": "기본",
  "计划": "계획",
  "目标": "목표",
