  "更改即时生效，仅保存在当前浏览器。": "변경 사항은 즉시 적용되며 이 브라우저에만 저장됩니다.",
  "恢复默认设置": "설정 재설정",
  "配置 Bark 或 ntfy 后，手机锁屏也可接收提醒。": "잠금 화면에서 알림을 받으려면 Bark 또는 ntfy를 설정하세요.",
  "选择手机推送方式": "전화 알림 서비스를 선택하세요",
  "iPhone 推荐安装 Bark，Android 可使用 ntfy。允许系统通知和锁屏显示；两个通道可以同时开启。": "iPhone에서는 Bark를 사용하고 Android에서는 ntfy를 사용하세요. 시스템 및 잠금 화면 알림을 허용합니다. 두 채널을 함께 활성화할 수 있습니다.",
  "填写接收信息": "알림 대상을 입력하세요",
  "Bark：填写手机 App 首页推送地址中的服务地址与 Device Key。ntfy：生成随机主题，并在手机订阅相同服务与主题。": "Bark: 전화 앱 홈 화면의 푸시 URL에서 서버 URL 및 장치 키를 입력합니다. ntfy: 임의의 주제를 생성하고 휴대폰에서 동일한 서버 및 주제를 구독합니다.",
  "开启需要的通道，点击底部“保存配置”，再分别发送测试通知。请在手机确认收到；服务接受不等于手机已收到。": "사용할 알림 채널을 켜고 설정을 저장한 뒤 테스트하세요. 서버가 요청을 받았더라도 실제 알림 수신 여부는 휴대폰에서 확인해야 합니다.",
  "先核对 Bark 服务地址与 Device Key，或 ntfy 服务地址、主题和 Token；自建 Bark 的设备需在该服务注册。": "Bark 서버 및 장치 키를 확인하거나 ntfy 서버, 주제 및 토큰을 확인하세요. 자체 호스팅 Bark의 경우 해당 서버에 전화기를 등록하십시오.",
  "服务已接受但手机没提示：检查系统通知权限、专注模式和手机网络。Android 还需允许 ntfy 在后台运行。": "서버가 알림을 수락했지만 전화기가 무음 상태인 경우 알림 권한, 집중 모드 및 연결을 확인하세요. Android는 또한 ntfy가 백그라운드에서 실행되도록 허용해야 합니다.",
  "登录设备": "로그인된 기기",
  "登录有效期（小时）": "로그인 유효 기간(시간)",
  "默认 12 小时；0 表示不自动过期。网关重启保留登录。修改账号、密码、登录方式或有效期后，重启网关将要求重新登录。清除浏览器数据或更换访问域名也需要重新登录。": "기본값: 12시간. 자동 만료를 사용하지 않으려면 0을 설정합니다. 로그인은 게이트웨이를 다시 시작해도 유지됩니다. 계정, 비밀번호, 로그인 모드 또는 유효성을 변경하려면 게이트웨이를 다시 시작한 후 다시 로그인해야 합니다. 브라우저 데이터를 지우거나 액세스 호스트 이름을 변경하는 경우에도 다시 로그인해야 합니다.",
  "刷新设备列表": "장치 새로 고침",
  "每条记录代表一次浏览器登录。撤销登录会要求重新验证；封禁 IP 会同时阻止使用该 IP 的所有设备，包括重新登录。": "각 항목은 브라우저 로그인입니다. 취소하려면 다시 인증이 필요합니다. IP를 차단하면 새 로그인을 포함하여 해당 IP를 사용하는 모든 장치가 거부됩니다.",
  "网页无法读取网卡 MAC。手机可能使用私有 MAC，IP 也会随网络变化；共用公网 IP 的设备会一起受到 IP 规则影响。": "웹 페이지는 네트워크 MAC 주소를 읽을 수 없습니다. 전화기는 개인 MAC 주소를 사용할 수 있으며 IP는 네트워크에 따라 변경될 수 있습니다. 공용 IP를 공유하는 장치는 동일한 IP 규칙의 영향을 받습니다.",
  "IP 访问规则": "IP 액세스 규칙",
  "仅允许白名单中的 IP": "허용 목록에 있는 IP만 허용",
  "白名单 · 每行一个 IP": "허용 목록 · 한 줄에 IP 1개",
  "黑名单 · 每行一个 IP": "차단 목록 · 한 줄에 하나의 IP",
  "黑名单优先。规则保存后立即生效，被排除的登录会被撤销。规则不影响电脑端管理，可在这里解除限制。": "차단 목록이 우선순위를 갖습니다. 저장하면 규칙이 즉시 적용되고 제외된 로그인이 취소됩니다. 데스크톱 관리는 계속 사용 가능하므로 여기에서 제한 사항을 제거할 수 있습니다.",
  "代理 IP 设置（高级）": "프록시 IP 설정(고급)",
  "可信代理 IP · 每行一个": "신뢰할 수 있는 프록시 IP · 한 줄에 하나씩",
  "仅在使用 NAS 等 HTTPS 反向代理时填写直连网关的代理 IP。代理必须覆盖或追加 X-Forwarded-For；本机 HTTPS 隧道自动受信任。未正确转发时显示代理 IP，封禁它会影响所有经该代理访问的设备。": "NAS 또는 기타 HTTPS 역방향 프록시의 경우 게이트웨이에 직접 연결되는 IP를 입력합니다. 프록시는 X-Forwarded-For를 덮어쓰거나 추가해야 합니다. 로컬 HTTPS 터널은 자동으로 신뢰됩니다. 전달하지 않으면 목록에 프록시 IP가 표시됩니다. 이를 차단하면 해당 프록시를 사용하는 모든 장치에 영향을 미칩니다.",
  "保存 IP 规则": "IP 규칙 저장",
  "暂无有效登录记录。": "활성 로그인 기록이 없습니다.",
  "未知浏览器": "알 수 없는 브라우저",
  "代理 IP（未提供客户端地址）": "프록시 IP(클라이언트 주소를 사용할 수 없음)",
  "经可信代理转发": "신뢰할 수 있는 프록시에 의해 전달됨",
  "直连地址": "직접 연결",
  "登录时间：": "로그인:",
  "可连接": "도달 가능",
  "连接不可用": "연결할 수 없음",
  "正在重试连接…": "연결을 다시 시도하는 중…",
  "下次自动重试：": "다음 자동 재시도:",
  "重试 SSH 连接": "SSH 연결 재시도",
  "最近访问：": "마지막으로 본 시간:",
  "有效期至：": "만료:",
  "不自动过期": "자동 만료 없음",
