  "NAS 上游请使用电脑的局域网地址，不能使用回环地址": "루프백 주소가 아닌 컴퓨터의 LAN 주소를 NAS 업스트림으로 사용합니다.",
  "NAS 可访问的电脑地址": "NAS에서 연결할 수 있는 컴퓨터 주소",
  "NAS 方式需要开启局域网访问并填写 NAS 可达的电脑 HTTP 地址": "NAS 액세스에는 LAN 청취 및 컴퓨터의 HTTP 주소가 필요합니다.",
  "SSH 主机": "SSH 호스트",
  "SSH 目标请填写已有 Host 别名或 user@hostname，不含空格和命令参数": "공백이나 명령 옵션 없이 기존 SSH 호스트 별칭 또는 user@hostname을 입력하세요.",
  "cloudflared 可执行文件": "cloudflared 실행 파일",
  "iPhone 和 Android 安装 ntfy 并订阅同一主题，再在手机聊天中开启“待确认提醒”。": "iPhone 또는 Android에 ntfy를 설치하고 동일한 주제를 구독하세요. 그런 다음 휴대폰 채팅에서 알림을 활성화하세요.",
  "ntfy Token 格式不正确": "잘못된 ntfy 토큰",
  "ntfy 主题只允许 1–64 位字母、数字、下划线和短横线": "ntfy 주제에는 1~64자의 문자, 숫자, 밑줄 또는 하이픈이 포함되어야 합니다.",
  "ntfy 手机安装说明 ↗": "ntfy 휴대폰 설정 가이드 ↗",
  "ntfy 推送": "ntfy 알림",
