  "■ 停止": "■ 정지",
  "。在下方生成随机主题，再把完整主题复制到手机 ntfy 中订阅；主题会自动创建。": ". 아래에서 임의의 주제를 생성하고 ntfy 전화 앱에서 정확한 주제를 구독하세요. 주제는 자동으로 생성됩니다.",
  "不允许的界面来源": "이 UI 소스는 허용되지 않습니다.",
