  "从一条聊天继续": "채팅 계속하기",
  "任务在电脑运行 · 沿用桌面模型设置": "컴퓨터에서 실행됩니다. · 데스크톱 모델 설정을 사용합니다.",
  "你": "사용자",
  "使用临时外网入口时需要": "임시 외부 액세스에 필요합니다.",
  "使用网关自己的账号密码。": "게이트웨이의 고유한 사용자 이름과 비밀번호를 사용합니다.",
  "保存配置": "설정 저장",
  "保存并启动网关后可检测入口。": "게이트웨이를 저장하고 시작한 후 이 항목을 확인하십시오.",
  "保存，再发送测试通知": "저장한 후 테스트 알림 보내기",
  "停止": "중지",
  "允许修改文件？": "파일 변경을 허용하시겠습니까?",
  "允许局域网访问": "LAN 액세스 허용",
  "允许本轮权限？": "이번 차례에 권한을 허용하시겠습니까?",
  "允许运行此命令？": "이 명령을 허용하시겠습니까?",
  "先核对手机与电脑的服务地址、主题完全一致；服务拒绝访问时，检查 Token 和主题权限，匿名首测可换一个随机主题。": "휴대폰과 컴퓨터가 정확히 동일한 서버와 주제를 사용하는지 확인하세요. 접근이 거부되면 토큰 및 주제 권한을 확인하거나 익명 테스트를 위해 새로운 무작위 주제를 시도해보세요.",
  "免密访问": "비밀번호 없는 액세스",
  "入口没有连接到当前网关；请检查反代目标，旧版网关须先更新并重启": "이 항목은 현재 게이트웨이에 도달하지 않습니다. 프록시 대상을 확인하십시오. 먼저 이전 게이트웨이를 업데이트하고 다시 시작하세요.",
  "入口返回的不是网关响应，请检查反代目标": "항목이 게이트웨이 응답을 반환하지 않았습니다. 프록시 대상 확인",
  "公共匿名主题没有访问控制，知道主题名的人可读写。请使用随机长名称，首测保留“显示聊天标题”为关闭；正式使用可选择受保护主题。": "공개 익명 주제에는 액세스 제어가 없습니다. 주제를 아는 사람은 누구나 읽고 게시할 수 있습니다. 긴 임의의 이름을 사용하고 첫 번째 테스트에서는 채팅 제목을 숨기십시오. 정기적인 사용을 위해 보호된 주제를 고려하십시오.",
  "公共匿名主题的 Token 留空。勾选“开启手机通知”，点击底部“保存配置”，然后“发送测试通知”。以手机实际收到为准。": "공개 익명 주제의 경우 토큰을 비워 두세요. 알림을 활성화하고 설정을 저장한 다음 테스트 알림을 보냅니다. 휴대폰으로 영수증을 확인하세요.",
  "在手机聊天的“提醒”中开启订阅，可为每个会话单独选择“运行完成后通知”。关闭网页后仍继续监听；取消关注即可停止该聊天提醒。": "전화 채팅에서 미리 알림을 열어 구독하고 선택적으로 해당 채팅에 대한 완료 알림을 활성화하세요. 페이지를 닫은 후에도 모니터링은 계속됩니다. 중지하려면 알림을 끄세요.",
  "关闭 Skill 选择": "스킬 선택 창 닫기",
  "关闭新建聊天": "새 채팅 대화 상자 닫기",
  "关闭模型设置": "모델 설정 닫기",
  "关闭窗口后，网关继续运行。": "이 창을 닫은 후에도 게이트웨이는 계속 실행됩니다.",
  "其他连接配置": "추가 연결",
