  "加载更早内容": "이전 메시지 로드",
  "加载更多": "더 불러오기",
  "历史加载失败，点击重试": "기록을 로드할 수 없습니다. 다시 시도하려면 클릭하세요.",
  "历史记录": "저장된 기록",
