  "发送测试通知": "테스트 알림 보내기",
  "发送结果待确认": "전송 결과 미확인",
  "取消": "취소",
  "可以同时启用局域网、临时 Cloudflare 和多个固定入口。所有入口连接同一个电脑网关，共用登录账号。": "LAN, 임시 Cloudflare 및 여러 고정 항목을 함께 실행할 수 있습니다. 모든 항목은 동일한 컴퓨터 게이트웨이에 도달하고 동일한 로그인을 사용합니다.",
  "可选，例如家中 NAS": "선택 사항(예: 홈 NAS",
  "同一 SSH 目标的回环端口不能重复": "동일한 SSH 대상에 대한 각 연결에는 서로 다른 루프백 포트가 필요합니다.",
  "启动与数据目录": "시작 및 데이터 디렉터리",
