  "启动网关时自动建立临时 HTTPS 隧道，需要在运行配置中选择 cloudflared。临时地址可能变化；同一网关只需一个临时入口，可与固定入口同时启用。": "임시 HTTPS 터널은 게이트웨이로 시작됩니다. 런타임 설정에서 cloudflared를 선택합니다. URL는 변경될 수 있습니다. 게이트웨이당 하나의 임시 항목만 필요합니다. 고정 항목이 함께 실행될 수 있습니다.",
  "启动网关，在手机浏览器刷新并打开聊天，点击“提醒”，勾选“开启聊天提醒”并保存。随后让 Codex 提出一次选择，锁屏检查是否收到待确认通知。": "게이트웨이를 시작하고 전화 페이지를 새로 고치고 채팅을 엽니다. 알림을 열고 채팅 알림을 활성화한 후 저장하세요. 그런 다음 Codex에게 선택 사항을 제시하도록 요청하세요. 휴대폰을 잠그고 알림을 확인하세요.",
  "启用此连接": "이 연결을 활성화합니다",
  "已有穿透 / 反向代理": "기존 터널/역방향 프록시",
  "可选，例如家里电脑": "선택 사항(예: 가정용 컴퓨터",
  "手机访问地址（HTTPS）": "전화 액세스 주소(HTTPS)",
  "先在你的穿透或反向代理中配置 HTTPS，再将手机访问地址粘贴到这里。地址只填写域名或 IP 与可选端口，不含路径。": "터널 또는 역방향 프록시에서 HTTPS를 구성한 다음 여기에 전화 액세스 주소를 붙여넣습니다. 경로 없이 도메인 또는 선택적 포트가 있는 IP만 입력하세요.",
  "穿透或反向代理的 HTTP 目标地址": "터널 또는 역방향 프록시의 HTTP 대상",
  "复制目标地址": "대상 주소 복사",
  "目标地址已复制。": "대상 주소가 복사되었습니다.",
  "高级：目标所在位置": "고급: 대상 위치",
  "穿透或反向代理运行在": "터널 또는 역방향 프록시는 다음에서 실행됩니다.",
  "这台电脑": "이 컴퓨터",
  "NAS 或另一台设备": "NAS 또는 다른 장치",
