  "需要开启局域网访问，填写另一台设备能访问的电脑 HTTP 地址，端口与网关一致。": "LAN 액세스를 활성화하고 게이트웨이 포트를 사용하여 다른 장치에서 연결할 수 있는 컴퓨터 HTTP 주소를 입력합니다.",
  "固定 HTTPS · 需完成服务器部署": "HTTPS 수정 · 서버 설정 필요",
