  "在电脑 App 的已有项目中创建空聊天，之后可在手机发送消息。电脑会打开这条聊天。": "데스크톱 앱에 저장된 프로젝트에 빈 채팅을 만든 다음 휴대폰에서 메시지를 보내세요. 컴퓨터에서 이 채팅이 열립니다.",
