  "填写 NAS 可达的电脑 HTTP 地址，端口与网关一致。需要开启局域网访问；两端网络不通时，先建立路由或使用自有服务器 + SSH。": "게이트웨이 포트를 사용하여 NAS에서 연결할 수 있는 컴퓨터의 HTTP 주소를 입력합니다. LAN 액세스를 활성화합니다. 네트워크가 서로 연결할 수 없는 경우 먼저 경로를 설정하거나 SSH 서버 연결을 사용하십시오.",
  "复制给部署 Agent": "배포 에이전트용 사본",
