  "尚未开启手机通知：填写并保存后，先发送测试通知。": "알림이 꺼져 있습니다. 설정을 입력하고 저장한 후 테스트 알림을 보냅니다.",
  "尚未添加外网连接。局域网可独立使用。": "아직 외부 연결이 없습니다. LAN 액세스는 독립적으로 작동합니다.",
  "局域网": "LAN",
  "局域网地址适用于同一网络；外网访问使用 HTTPS 入口。": "같은 네트워크에서는 LAN 주소를 사용하세요. 외부에서 접속하려면 HTTPS 주소를 사용하세요.",
  "展开完整内容": "전체 콘텐츠 표시",
  "已保存提交的配置，仍有新修改待保存。": "제출된 설정이 저장되었습니다. 새로운 수정 사항이 아직 저장되지 않았습니다.",
  "已保存；留空保留，服务地址变化时清除": "저장되었습니다. 보관하려면 비워두세요. 서버를 변경하면 삭제됩니다.",
