  "已切换网关目录，原来的网关进程继续运行。": "게이트웨이 디렉터리가 변경되었습니다. 이전 게이트웨이 프로세스가 아직 실행 중입니다.",
  "已加入待发送队列": "전송 대기열에 추가됨",
