  "已启用的连接不能使用相同 HTTPS 地址": "활성화된 연결은 다른 HTTPS 주소를 사용해야 합니다.",
  "已开启 · ": "활성화됨 ·",
  "已开启待确认提醒，关闭网页后仍会通知": "알림이 활성화되었습니다. 이 페이지를 닫은 후에도 알림이 계속 표시됩니다.",
