  "开启通知前请填写 ntfy 主题": "알림을 활성화하기 전에 ntfy 주제를 입력하세요.",
  "当前显示已保存的历史。请在电脑 App 打开此聊天后重新连接。": "저장된 기록을 표시합니다. 데스크톱 앱에서 이 채팅을 열고 다시 연결하세요.",
  "当前网关版本不支持聊天提醒，请在首页停止后重新启动网关，再刷新手机网页。": "이 게이트웨이 버전은 알림을 지원하지 않습니다. 개요에서 중지했다가 다시 시작한 다음 전화 페이지를 새로 고치세요.",
  "当前网关版本较旧，重启后启用通知能力。": "이 게이트웨이 버전은 이전 버전입니다. 알림 지원을 활성화하려면 다시 시작하세요.",
  "待确认请求": "확인 대기 중",
  "待确认请求通知": "보류 중인 확인에 대한 알림",
  "手动填写的跳转地址优先；要自动跟随固定域名，请留空。默认不包含聊天标题和内容。临时域名变化后，旧通知的链接可能失效。自建 ntfy 的 iPhone 即时通知需要配置 APNs 上游。": "수동으로 입력한 클릭 URL가 우선순위를 갖습니다. 고정 도메인을 자동으로 팔로우하려면 비워두세요. 채팅 제목과 내용은 기본적으로 제외됩니다. 이전 알림에 만료된 임시 링크가 있을 수 있습니다. 자체 호스팅 ntfy는 즉각적인 iPhone 알림을 위해 APN 업스트림이 필요합니다.",
  "手机关闭网页后，已关注聊天仍会继续提醒。": "시청 중인 채팅은 전화 페이지가 닫힌 후에도 계속 알림을 보냅니다.",
  "手机安装 ntfy": "휴대폰에 ntfy를 설치하세요",
