  "手机通知": "휴대폰 알림",
  "打开": "열기",
  "登录电脑后自动启动": "로그인 시 자동으로 시작",
  "开启后，登录电脑时自动启动网关。": "컴퓨터에 로그인할 때 게이트웨이를 자동으로 시작합니다.",
  "请在系统设置的登录项中允许此应用。": "시스템 설정의 로그인 항목에서 이 앱을 허용하세요.",
  "登录自启设置保存失败，请重试。": "로그인 시작 설정을 저장하지 못했습니다. 다시 시도해 주세요.",
  "登录自启开关格式错误": "잘못된 로그인 시작 설정",
  "请使用已安装的桌面应用设置登录自启。": "설치된 데스크톱 앱에서 로그인 시작을 구성합니다.",
  "请将应用安装到固定目录后设置登录自启。": "로그인 시작을 활성화하기 전에 영구 위치에 앱을 설치하십시오.",
