  "推送服务请使用 HTTPS；HTTP 仅用于本机测试": "알림 서버에는 HTTPS를 사용합니다. HTTP는 로컬 테스트에만 지원됩니다.",
  "提交回复": "답장 제출",
  "聊天通知设置": "채팅 알림 설정",
  "关闭通知设置": "알림 설정 닫기",
  "运行完成后通知": "실행이 완료되면 알림",
  "需要确认或回复时通知，关闭网页后仍继续监听。": "확인이나 답변이 필요할 때 알립니다. 페이지를 닫은 후에도 모니터링이 계속됩니다.",
  "仅对当前聊天生效。正常完成时通知，手动停止或失败时不通知。": "이 채팅에만 적용됩니다. 중지되거나 실패한 실행을 제외하고 성공적인 완료를 알립니다.",
  "聊天提醒设置已保存": "채팅 알림 설정이 저장되었습니다.",
  "请先开启此聊天提醒": "먼저 이 채팅에 대한 알림을 활성화하세요",
  "ntfy 发送失败，将在提醒仍开启时重试完成通知；待确认通知仅在请求仍待处理时重试。请检查服务地址、认证和网络。": "ntfy 전송에 실패했습니다. 활성화된 동안 완료 알림이 다시 시도됩니다. 확인 알림은 보류 중에만 재시도됩니다. 서버, 인증, 네트워크를 확인하세요.",
  "提醒": "채팅 알림",
  "提醒已开": "채팅 알림 켜짐",
  "提醒开关格式不正确": "채팅 알림 전환 값이 올바르지 않습니다.",
