  "各日志来源内最新记录在最上方，同一错误的详细堆栈保持原顺序。": "최신 레코드는 각 로그 소스 내에서 먼저 나타납니다. 스택 추적 선은 원래 순서를 유지합니다.",
  "最近一次发送：": "마지막으로 보낸 날짜:",
