  "服务器 SSH 目标": "서버 SSH 대상",
  "服务器回环端口": "서버 루프백 포트",
  "服务器回环端口须为 1024–65535": "서버 루프백 포트는 1024–65535여야 합니다.",
  "服务器 HTTPS 入口使用 443 端口；已有其他入口请选择已有穿透 / 反向代理": "자동 서버 HTTPS는 포트 443을 사용합니다. 다른 포트에 있는 기존 항목의 경우 기존 터널 / 역방향 프록시를 선택합니다.",
  "服务已接受但手机没提示：检查 ntfy 订阅连接、系统通知权限和专注模式。Android 可开启即时投递并允许后台运行；自建服务的 iPhone 即时通知需要配置 APNs 上游。": "서버가 알림을 수락했지만 전화기가 무음 상태인 경우 ntfy 구독, OS 알림 권한 및 집중 모드를 확인하세요. Android에서는 즉시 전달 및 백그라운드 활동을 허용합니다. 자체 호스팅 ntfy는 즉각적인 iPhone 알림을 위해 APN 업스트림이 필요합니다.",
  "未启动": "중지됨",
  "未开启": "꺼짐",
  "未找到 OpenSSH 客户端；请先安装或启用系统 SSH 客户端": "OpenSSH 클라이언트를 찾을 수 없습니다. 먼저 시스템 SSH 클라이언트를 설치하거나 활성화하세요.",
