  "正在读取已安装 Skill…": "설치된 스킬 로드 중…",
  "正在读取更早内容…": "이전 콘텐츠 로드 중…",
  "正在读取最近内容…": "최근 콘텐츠 로드 중…",
  "正在读取电脑项目…": "데스크톱 프로젝트 로드 중…",
  "正在读取聊天…": "채팅 불러오는 중…",
  "正在连接…": "연결 중…",
  "正在连接桌面，可先阅读已保存的历史。": "데스크톱에 연결 중입니다. 그동안 저장된 기록을 읽을 수 있습니다.",
  "此网关已启用免密访问。": "이 게이트웨이에서는 비밀번호 없는 액세스가 활성화됩니다.",
  "每个网关只需启用一个临时 Cloudflare 入口；可同时启用其他连接方式": "게이트웨이당 하나의 임시 Cloudflare 항목만 필요합니다. 다른 연결 유형을 동시에 활성화할 수 있습니다.",
  "每行一个，不含路径": "경로 없이 한 줄에 하나씩",
  "没有匹配的 Skill": "일치하는 스킬이 없습니다.",
  "没有找到聊天。": "채팅을 찾을 수 없습니다.",
  "测试通知只检查手机接收；聊天提醒还需要电脑、网关、原 Codex App 及相关 SSH 连接在线。": "테스트 알림은 휴대폰의 알림 수신 여부만 확인합니다. 채팅 알림을 받으려면 컴퓨터, 게이트웨이, 원래 Codex 앱과 필요한 SSH 연결이 온라인 상태여야 합니다.",
  "消息内容": "메시지",
  "消息可能已送达，请检查聊天记录。再次点击不会重复提交。": "메시지가 전달되었을 수 있습니다. 채팅 기록을 확인하세요. 다시 클릭하면 두 번 제출되지 않습니다.",
  "点击生成随机主题": "임의의 주제를 생성하려면 클릭하세요.",
  "生成随机主题": "무작위 주제 생성",
  "电脑": "컴퓨터",
  "电脑上游地址的端口须与网关监听端口一致": "업스트림 포트는 게이트웨이 수신 포트와 일치해야 합니다.",
  "电脑上的聊天": "컴퓨터에서 채팅",
  "电脑主动通过 SSH 连接服务器，适合校园网。使用现有 SSH 密钥或 ssh-agent；首次连接须在终端核对主机指纹。同一服务器的不同配置使用不同回环端口。": "컴퓨터는 캠퍼스 네트워크를 포함하여 SSH를 통해 서버에 연결됩니다. 기존 SSH 키 또는 ssh-agent를 사용합니다. 먼저 터미널에서 호스트 지문을 확인하세요. 동일한 서버에 대한 서로 다른 연결에는 서로 다른 루프백 포트가 필요합니다.",
  "电脑运行 · 手机接力": "컴퓨터에서 실행 · 휴대폰에서 계속",
