  "网关未启动。可先保存配置并导出部署包。": "게이트웨이가 중지되었습니다. 먼저 설정을 저장하고 ZIP 배포를 내보낼 수 있습니다.",
  "网关正在运行；固定入口是否可用，请点击检测。": "게이트웨이가 실행 중입니다. 확인을 클릭하여 수정된 항목을 확인합니다.",
