  "网络和运行路径在网关停止后可修改。模型、提供商和 Skill 沿用原 Codex 会话设置。": "네트워크 설정이나 프로그램 경로를 바꾸려면 먼저 게이트웨이를 중지하세요. 모델, 제공업체, 스킬은 원래 Codex 채팅의 설정을 사용합니다.",
