  "请填写有效的登录账号和登录方式": "유효한 사용자 이름과 로그인 방법을 입력하세요.",
  "请填写服务器的 SSH 目标": "서버의 SSH 대상을 입력하세요.",
  "请检查聊天记录。网关不会自动重发这条消息。": "채팅 기록을 확인하세요. 게이트웨이는 이 메시지를 자동으로 다시 보내지 않습니다.",
