  "返回聊天列表": "채팅으로 돌아가기",
  "这是网关的访问地址允许列表。只有你已在其他地方配置好 HTTPS 反向代理或隧道，并且需要额外域名访问时，才在这里填写，例如 https://codex.try2love.com。填写地址不会创建隧道、配置 DNS 或申请证书；代理仍须保留该域名的 Host。上方连接配置中的固定域名会自动加入，无需重复填写；只用局域网或临时 Cloudflare 时留空即可。": "게이트웨이의 주소 허용 목록입니다. HTTPS 역방향 프록시 또는 터널이 https://codex.try2love.com.와 같이 다른 곳에 이미 구성되어 있는 추가 도메인에만 사용하십시오. URL를 추가해도 터널이 생성되지 않고, DNS를 구성하거나 인증서가 요청되지 않습니다. 프록시는 도메인의 호스트 헤더를 보존해야 합니다. 연결 카드의 고정 도메인은 자동으로 추가됩니다. LAN 또는 임시 Cloudflare 액세스만 사용하려면 이 항목을 비워 두세요.",
