  "下载地址发生跳转，已取消。请重新打开电脑附件。": "다운로드 리디렉션이 차단되었습니다. 컴퓨터에서 첨부 파일을 다시 엽니다.",
  "下载失败，请检查网络后重试": "다운로드에 실패했습니다. 네트워크를 확인하고 다시 시도하세요.",
  "请先扫码保存通知对应的电脑，再打开聊天。": "채팅을 열기 전에 알림의 컴퓨터를 스캔하고 저장하세요.",
  "请先连接并登录电脑网关": "먼저 컴퓨터의 게이트웨이에 연결하고 로그인하세요.",
  "登录已失效，请重新连接电脑": "로그인이 만료되었습니다. 컴퓨터에 다시 연결하십시오.",
