  "请在电脑 Preview 的手机通知中开启“手机 App 通知收件箱”并保存。": "데스크톱 미리보기의 알림 설정에서 ’모바일 앱 알림 받은 편지함’을 활성화하고 저장하세요.",
  "清空通知": "알림 지우기",
