  "开启任务通知": "작업 알림 켜기",
  "App 打开时提醒已连接电脑的新任务消息。离开 App 或锁屏后不保证通知；可在电脑端配置 Bark 或 ntfy。": "앱을 열어 둔 동안 저장된 컴퓨터의 새 작업 알림을 받습니다. 앱을 닫거나 화면을 잠그면 알림을 받지 못할 수 있습니다. 백그라운드 알림이 필요하면 컴퓨터에서 Bark 또는 ntfy를 설정하세요.",
  "测试本机通知": "로컬 알림 테스트",
  "10 秒后显示，用于检查手机的通知权限。": "알림 권한을 확인하기 위해 10초 후에 나타납니다.",
  "灵动岛与锁屏": "다이내믹 아일랜드 및 잠금 화면",
