  "从电脑菜单选择聊天跟踪。后台显示可能不是最新状态，打开 App 可继续同步。": "컴퓨터 메뉴에서 추적할 채팅을 선택하세요. 배경 상태가 최신이 아닐 수 있습니다. 앱을 열어 동기화하세요.",
