  "移除这台电脑": "이 컴퓨터 제거",
  "此预览尚未配置 Apple 推送签名。需要开发者账号和电脑端推送服务后才能启用后台任务提醒。": "Apple 푸시 서명이 구성되지 않았습니다. 백그라운드 알림에는 개발자 계정과 게이트웨이 푸시 서비스가 필요합니다.",
  "请在系统设置允许 Bridge Preview 通知。": "시스템 설정에서 Bridge 미리보기 알림을 허용합니다.",
  "手机通知测试": "모바일 알림 테스트",
