  "10 秒后显示本地测试通知，可以先锁屏。此测试不代表远程推送已经接通。": "10초 후에 로컬 테스트 알림이 나타납니다. 화면을 잠글 수 있습니다. 원격 푸시 전달을 확인하지는 않습니다.",
  "测试通知未能创建，请检查系统通知设置。": "테스트를 예약할 수 없습니다. 시스템 알림 설정을 확인하세요.",
  "移除这台电脑？": "이 컴퓨터를 제거하시겠습니까?",
