  "此预览尚未配置系统推送项目。当前仅同步收件箱；配置 Firebase 或厂商推送后才能启用后台任务提醒。": "시스템 푸시가 구성되지 않았습니다. 백그라운드 작업 알림에는 Firebase 또는 기기 공급업체의 푸시 서비스가 필요합니다.",
  "10 秒后显示本地测试通知，可以先返回桌面。此测试不代表远程推送已经接通。": "10초 후에 로컬 테스트 알림이 나타납니다. 앱을 종료해도 됩니다. 원격 푸시 전달을 확인하지는 않습니다.",
  "未获得权限，可继续粘贴地址使用。": "허가가 거부되었습니다. 연결하려면 주소를 붙여넣을 수 있습니다.",
