  "模型目录返回无效": "잘못된 모델 카탈로그 응답",
  "正在显示缓存 Skill，后台会自动刷新。": "캐시된 스킬을 보여줍니다. 백그라운드에서 새로 고쳐집니다.",
  "正在显示旧版缓存 Skill，后台会自动刷新。": "이전에 캐시된 스킬을 표시합니다. 백그라운드에서 새로 고쳐집니다.",
  "已失效 Skill": "사용할 수 없는 스킬",
  "桌面 App 连接已断开，正在等待重连": "데스크톱 연결이 끊어졌습니다. 다시 연결되기를 기다리고 있습니다.",
  "连续终端需要 Windows 10 1809 或更新版本": "연속 터미널에는 Windows 10 1809 이상이 필요합니다.",
  "松开刷新聊天列表": "채팅을 새로고침하려면 버튼을 놓으세요.",
  "下拉刷新聊天列表": "당겨서 채팅 새로고침",
  "正在刷新聊天列表…": "채팅 새로고침…",
  "聊天列表已更新": "채팅이 업데이트되었습니다.",
  "列表暂未更新，点击重试": "새로고침할 수 없습니다. 다시 시도하려면 탭하세요.",
  "正在读取项目…": "프로젝트 로드 중…",
  "命令输出": "명령 출력",
  "输入命令…": "명령을 입력하세요…",
  "终端命令": "터미널 명령",
  "运行 ↵": "실행 ↵",
  "命令终端 · 使用说明": "명령 터미널 · 도움말",
  "每条命令从项目目录运行，沿用当前系统用户权限。Enter 运行，Shift+Enter 换行。支持脚本与构建输出，暂不支持 vim、密码输入等交互式程序。单次最多运行 30 分钟。": "각 명령은 현재 사용자의 권한으로 프로젝트 디렉터리에서 시작됩니다. 실행을 입력하십시오. Shift+Enter는 줄을 삽입합니다. 명령 모드에서는 대화형 프로그램이 지원되지 않습니다. 최대 실행 시간: 30분.",
  "正在启动…": "시작 중…",
  " · 正在查询执行状态，不会重复执行。": "· 상태 확인 중; 명령은 두 번 실행되지 않습니다.",
  "已结束 · 退出码 ": "완료 · 종료 코드",
  " · 仅保留最近输出": "· 최근 출력만",
  "找不到这个会话": "채팅을 찾을 수 없습니다",
  "Codex 未完成侧边聊天操作，请检查模型接入和运行时版本": "Codex가 사이드 채팅 작업을 완료할 수 없습니다. 모델 연결 및 런타임 버전을 확인하세요.",
  "临时侧边聊天数量已达上限，请关闭不用的聊天；必要时重启网关": "임시 사이드 채팅이 너무 많습니다. 사용하지 않는 채팅을 종료하거나 게이트웨이를 다시 시작하세요.",
  "侧边聊天工作目录不一致，已取消创建": "작업 디렉터리가 일치하지 않아 사이드 채팅 생성이 취소되었습니다.",
  "侧边聊天已关闭或失效": "사이드 채팅이 폐쇄되었거나 만료되었습니다.",
  "侧边聊天已失效，请关闭后新建": "사이드 채팅이 만료되었습니다. 끝내고 새로 만드세요.",
  "侧边聊天执行失败，请检查模型接入后重试": "사이드 채팅이 실패했습니다. 모델 연결을 확인하고 다시 시도해 보세요.",
  "侧边聊天操作结果未确认，请刷新状态，不要重复发送": "작동이 확인되지 않았습니다. 다시 보내기 전에 상태를 새로 고치세요.",
  "侧边聊天的模型接入与主聊天不一致，已取消创建": "모델 연결이 상위 연결과 일치하지 않아 사이드 채팅 생성이 취소되었습니다.",
  "侧边聊天运行时已断开": "사이드 채팅 런타임 연결이 끊어졌습니다.",
  "同一消息标识不能用于不同内容": "ID 메시지는 다른 콘텐츠에 재사용할 수 없습니다.",
  "无效侧边聊天操作": "잘못된 사이드 채팅 작업",
  "无法确认临时分支，已取消创建": "임시 지점을 확인할 수 없습니다. 생성이 취소되었습니다.",
  "模型 ID 格式不正确": "잘못된 모델 ID",
  "此 Codex 运行时不支持临时侧边聊天，请更新 Codex": "이 런타임은 임시 사이드 채팅을 지원하지 않습니다. Codex를 업데이트하세요.",
  "此侧边聊天已关闭或已失效，请刷新标签": "사이드 채팅이 폐쇄되었거나 만료되었습니다. 이 탭을 새로 고칩니다.",
  "此次创建的侧边聊天已关闭，请重新打开标签后新建": "이 사이드 채팅이 종료되었습니다. 다른 탭을 만들려면 탭을 다시 여세요.",
