  "Online guide (English)": "온라인 가이드(영문)",
  "Confirm that all tasks in this configuration, including tasks in other clients, have finished and synchronize the shared Codex account? Do not start work in other clients until switching completes. The idle shared service exits normally only when needed.": "이 구성의 모든 작업(다른 클라이언트의 작업 포함)이 끝났는지 확인하고 공유 Codex 계정을 동기화하시겠습니까? 전환이 끝나기 전까지 다른 클라이언트에서 작업을 시작하지 마세요. 필요한 경우에만 유휴 공유 서비스를 정상 종료합니다.",
  "Confirm that all tasks, including tasks not shown on this web page, have finished and switch shared Codex access? Do not start work in other clients until switching completes. The desktop runtime quits normally and restarts only when needed.": "모든 작업(이 웹 페이지에 표시되지 않는 작업 포함)이 끝났는지 확인하고 공유 Codex 접속 설정을 전환하시겠습니까? 전환이 끝나기 전까지 다른 클라이언트에서 작업을 시작하지 마세요. 필요한 경우에만 데스크톱 런타임을 정상 종료 후 다시 시작합니다.",
  "This connection has queued or unconfirmed operations. Resolve them in the original client first.": "원래 클라이언트에서 대기 중이거나 결과가 확인되지 않은 작업을 먼저 처리하세요.",
