  "Quit the client before saving or switching accounts, or start the gateway to perform this action.": "계정을 저장하거나 전환하기 전에 클라이언트를 종료하세요. 또는 게이트웨이를 시작해 이 작업을 수행하세요.",
  "The account configuration has not taken effect. Try again.": "계정 구성이 반영되지 않았습니다. 다시 시도하세요.",
  "The account action did not finish. Check on your computer; the recovery backup has been kept.": "계정 작업을 완료하지 못했습니다. 컴퓨터에서 확인하세요. 복구용 백업은 보존했습니다.",
