  "Create a project session in the desktop client first": "먼저 데스크톱 클라이언트에서 프로젝트 대화를 만드세요.",
  "Preview images in the file list; turn off to show file type icons.": "파일 목록에서 이미지를 미리 봅니다. 끄면 파일 형식 아이콘이 표시됩니다.",
  "Remember me (expires after 7 inactive days)": "로그인 상태 유지(7일 동안 접속하지 않으면 만료)",
  "Standard web sign-in defaults to 12 hours; 0 disables expiry for web sign-ins. Remembered web sign-ins renew on use and expire after 7 inactive days. Mobile app sign-ins and pairing remain trusted until you sign out or revoke the device. Account or sign-in mode changes revoke all sign-ins; a password change can keep already bound phones.": "일반 웹 로그인은 기본 12시간이며, 0을 입력하면 웹 로그인 만료를 사용하지 않습니다. 로그인 상태를 유지하면 사용할 때마다 갱신되며 7일간 접속하지 않으면 만료됩니다. 모바일 앱 로그인과 페어링은 로그아웃하거나 해당 기기의 인증을 철회할 때까지 유지됩니다. 계정이나 로그인 방식을 바꾸면 모든 로그인이 철회됩니다. 비밀번호 변경 시 이미 연결된 휴대폰의 인증은 유지할 수 있습니다.",
  "Show account shortcut": "계정 바로가기 표시",
