  "Run completion notifications": "작업 완료 알림",
  "Applies to all chats. Override in chat reminders. Configure a notification channel first.": "모든 채팅에 적용됩니다. 채팅 알림에서 개별 설정을 바꿀 수 있습니다. 먼저 알림 채널을 설정하세요.",
  "The goal operation is not confirmed. Check its current state.": "목표 작업의 결과가 확인되지 않았습니다. 현재 상태를 확인하세요.",
  "Current account · Usage and reset cards": "현재 계정 · 사용량 및 재설정 카드",
