  "Valid for 5 minutes and one use. Anyone with this code can sign in: keep it private. Collapsing or refreshing revokes it. The mobile app stays signed in until you sign out or revoke it in Signed-in devices. Browsers follow the configured session duration.": "QR 코드는 5분 동안 한 번만 사용할 수 있습니다. 코드가 있으면 누구나 로그인할 수 있으므로 비공개로 보관하세요. 접거나 새로고침하면 코드가 철회됩니다. 모바일 앱은 로그아웃하거나 로그인된 장치에서 해당 기기의 인증을 철회할 때까지 로그인 상태를 유지합니다. 브라우저는 설정된 로그인 유효 기간을 따릅니다.",
